-- 0035_session_groups.sql — V23 Step 14: a group session is one row per
-- attendee sharing a session_group_id.
--
-- One slot, several clients (app and offline mixed). Stored as one
-- scheduled_workouts row per attendee, not one row plus a join table, so the
-- XOR constraint (scheduled_workouts_one_client) holds and every existing
-- policy, view and trigger keeps working unchanged: streaks, client status,
-- money, risk, attention, reminders, the per-row paid flag and
-- trg_increment_used_sessions (one package session per attendee who comes).
--
-- session_group_id: one uuid generated by the app per group slot, stamped on
-- every attendee's row. Null = a solo session. With a repeat, each date gets
-- its own session_group_id while every row shares the one series_id (0031):
-- the two columns are independent. No FK (there is no group table — the rows
-- ARE the group) and no RLS change: the trainer already owns every row.
-- A group's status (done / partly / planned / missed) is derived on read from
-- its rows, never stored.
--
-- Re-runnable.

alter table public.scheduled_workouts
  add column if not exists session_group_id uuid;

-- The attendance sheet and the calendar card read a trainer's group.
create index if not exists scheduled_workouts_session_group_idx
  on public.scheduled_workouts (trainer_id, session_group_id)
  where session_group_id is not null;
